 6	final class KahnTopologicalSorter implements TopologicalSorter {
 7	    @Override
 8	    public List<Integer> sort(DirectedGraph graph) {
 9	        int[] indegree = buildIndegreeTable(graph);
10	        Deque<Integer> readyVertices = collectZeroIndegreeVertices(indegree);
11	        List<Integer> order = new ArrayList<>(graph.vertexCount());
12	
13	        while (!readyVertices.isEmpty()) {
14	            int vertex = readyVertices.removeFirst();
15	            order.add(vertex);
16	            for (int next : graph.neighborsOf(vertex)) {
17	                indegree[next]--;
18	                if (indegree[next] == 0) {
19	                    readyVertices.addLast(next);
20	                }
21	            }
22	        }
23	
24	        validateAcyclic(graph, order);
25	        return order;
26	    }
